#!/usr/bin/env python3
"""Add a cover page (title + current date) to report.pdf using pure Python.

No external PDF libraries or CLI tools are available in this environment, so we
implement a minimal PDF object model, parser, serializer, and merger.
"""

import datetime
import re
from pathlib import Path

# ----------------------------- PDF object model -----------------------------

WS = b"\x00\t\n\x0c\r "


class Name:
    def __init__(self, s):
        self.s = s

    def __repr__(self):
        return "/" + self.s


class StringTok:
    """A PDF string, keeping the original token bytes verbatim."""

    def __init__(self, raw):
        self.raw = raw


class Ref:
    def __init__(self, num, gen=0):
        self.num = num
        self.gen = gen

    def __repr__(self):
        return f"{self.num} {self.gen} R"


class Keyword:
    def __init__(self, s):
        self.s = s


class Dict:
    def __init__(self, pairs=None):
        self.pairs = pairs if pairs is not None else []

    def get(self, key, default=None):
        for k, v in self.pairs:
            if k == key:
                return v
        return default

    def set(self, key, value):
        for i, (k, v) in enumerate(self.pairs):
            if k == key:
                self.pairs[i] = (key, value)
                return
        self.pairs.append((key, value))

    def keys(self):
        return [k for k, _ in self.pairs]


# ----------------------------- PDF value parser -----------------------------


class PDFParser:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.n = len(data)

    def skip_ws(self):
        d = self.data
        n = self.n
        while self.pos < n:
            c = d[self.pos]
            if c in WS:
                self.pos += 1
            elif c == 0x25:  # '%' comment
                while self.pos < n and d[self.pos] not in b"\r\n":
                    self.pos += 1
            else:
                break

    def parse_value(self):
        self.skip_ws()
        d = self.data
        c = d[self.pos]
        if c == ord("<"):
            if d[self.pos + 1:self.pos + 2] == b"<":
                return self.parse_dict()
            return self.parse_hex_string()
        if c == ord("("):
            return self.parse_literal_string()
        if c == ord("["):
            return self.parse_array()
        if c == ord("/"):
            return self.parse_name()
        if c in b"+-.0123456789":
            return self.parse_number_or_ref()
        m = re.match(rb"[A-Za-z]+", d[self.pos:])
        kw = m.group(0).decode()
        self.pos += len(m.group(0))
        return Keyword(kw)

    def parse_dict(self):
        self.pos += 2  # '<<'
        pairs = []
        while True:
            self.skip_ws()
            if self.data[self.pos:self.pos + 2] == b">>":
                self.pos += 2
                break
            key = self.parse_value()
            assert isinstance(key, Name), f"dict key not a name: {key!r}"
            val = self.parse_value()
            pairs.append((key.s, val))
        return Dict(pairs)

    def parse_array(self):
        self.pos += 1  # '['
        arr = []
        while True:
            self.skip_ws()
            if self.data[self.pos:self.pos + 1] == b"]":
                self.pos += 1
                break
            arr.append(self.parse_value())
        return arr

    def parse_name(self):
        d = self.data
        n = self.n
        self.pos += 1  # '/'
        start = self.pos
        while self.pos < n:
            c = d[self.pos]
            if c in WS or c in b"()<>[]{}/%":
                break
            self.pos += 1
        raw = d[start:self.pos]
        out = bytearray()
        i = 0
        while i < len(raw):
            if raw[i:i + 1] == b"#" and i + 2 < len(raw):
                out.append(int(raw[i + 1:i + 3], 16))
                i += 3
            else:
                out.append(raw[i])
                i += 1
        return Name(bytes(out).decode("latin-1"))

    def parse_literal_string(self):
        d = self.data
        n = self.n
        start = self.pos
        self.pos += 1  # '('
        depth = 1
        while self.pos < n and depth:
            c = d[self.pos]
            if c == 0x5C:  # backslash
                nxt = d[self.pos + 1:self.pos + 2]
                if nxt in (b"\r", b"\n"):
                    self.pos += 2
                    if nxt == b"\r" and d[self.pos:self.pos + 1] == b"\n":
                        self.pos += 1
                    continue
                self.pos += 2
                continue
            if c == ord("("):
                depth += 1
            elif c == ord(")"):
                depth -= 1
            self.pos += 1
        self.pos += 1  # closing ')'
        return StringTok(d[start:self.pos])

    def parse_hex_string(self):
        d = self.data
        start = self.pos
        self.pos += 1  # '<'
        while self.pos < self.n and d[self.pos] != ord(">"):
            self.pos += 1
        self.pos += 1
        return StringTok(d[start:self.pos])

    def parse_number_or_ref(self):
        d = self.data
        n = self.n
        start = self.pos
        while self.pos < n and d[self.pos] in b"+-.0123456789":
            self.pos += 1
        tok = d[start:self.pos]
        if b"." in tok:
            val = float(tok)
        else:
            val = int(tok)
        save = self.pos
        self.skip_ws()
        m2 = re.match(rb"(\d+)\s+", d[self.pos:])
        if m2:
            p2 = self.pos + m2.end()
            p3 = p2
            while p3 < n and d[p3] in WS:
                p3 += 1
            if d[p3:p3 + 1] == b"R":
                self.pos = p3 + 1
                return Ref(int(tok), int(m2.group(1)))
        self.pos = save
        return val


# ----------------------------- Document parsing -----------------------------

OBJ_PAT = re.compile(rb"(\d+)\s+(\d+)\s+obj\b")


def parse_document(data):
    """Return {objnum: (value_tree, stream_bytes_or_None)} for all objects."""
    objs = {}
    pos = 0
    while True:
        m = OBJ_PAT.search(data, pos)
        if not m:
            break
        num, gen = int(m.group(1)), int(m.group(2))
        p = PDFParser(data, m.end())
        tree = p.parse_value()
        stream = None
        if isinstance(tree, Dict):
            q = PDFParser(data, p.pos)
            q.skip_ws()
            if q.data[q.pos:q.pos + 6] == b"stream":
                s = q.pos + 6
                if data[s:s + 2] == b"\r\n":
                    s += 2
                elif data[s:s + 1] in (b"\n", b"\r"):
                    s += 1
                length = tree.get("Length")
                if isinstance(length, int):
                    stream = data[s:s + length]
                    e = s + length
                else:
                    e = data.find(b"endstream", s)
                    stream = data[s:e]
                e2 = data.find(b"endobj", e)
                pos = e2 + len(b"endobj")
                objs[num] = (tree, stream)
                continue
        e = data.find(b"endobj", p.pos)
        pos = e + len(b"endobj")
        objs[num] = (tree, None)
    return objs


def parse_trailer(data):
    """Return the trailer Dict (last 'trailer' keyword followed by a dict)."""
    for m in reversed(list(re.finditer(rb"\btrailer\b", data))):
        p = PDFParser(data, m.end())
        try:
            v = p.parse_value()
        except Exception:
            continue
        if isinstance(v, Dict) and v.get("Root") is not None:
            return v
    raise RuntimeError("No trailer with /Root found")


# ----------------------------- Serialization --------------------------------


def ser(v):
    if isinstance(v, Ref):
        return f"{v.num} {v.gen} R".encode()
    if isinstance(v, Name):
        return b"/" + v.s.encode("latin-1")
    if isinstance(v, StringTok):
        return v.raw
    if isinstance(v, Keyword):
        return v.s.encode()
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, float):
        return repr(v).encode()
    if isinstance(v, Dict):
        out = b"<<\n"
        for k, val in v.pairs:
            out += b"/" + k.encode("latin-1") + b" " + ser(val) + b"\n"
        return out + b">>"
    if isinstance(v, list):
        return b"[ " + b" ".join(ser(x) for x in v) + b" ]"
    raise TypeError(f"cannot serialize {type(v)}")


def renumber(tree, mapping):
    if isinstance(tree, Ref):
        return Ref(mapping.get(tree.num, tree.num), tree.gen)
    if isinstance(tree, Dict):
        return Dict([(k, renumber(v, mapping)) for k, v in tree.pairs])
    if isinstance(tree, list):
        return [renumber(v, mapping) for v in tree]
    return tree


def collect_refs(v, out):
    if isinstance(v, Ref):
        out.append(v)
    elif isinstance(v, Dict):
        for _, x in v.pairs:
            collect_refs(x, out)
    elif isinstance(v, list):
        for x in v:
            collect_refs(x, out)


# ----------------------------- Cover page content ---------------------------

# Helvetica-Bold AFM widths (per 1000 units) for the characters we need.
WIDTHS = {
    "A": 722, "B": 722, "C": 722, "D": 722, "E": 667, "F": 611, "G": 778,
    "H": 722, "I": 278, "J": 556, "K": 722, "L": 611, "M": 833, "N": 722,
    "O": 778, "P": 667, "Q": 778, "R": 722, "S": 667, "T": 611, "U": 722,
    "V": 667, "W": 944, "X": 667, "Y": 667, "Z": 611,
    "a": 556, "b": 556, "c": 500, "d": 556, "e": 556, "f": 278, "g": 556,
    "h": 556, "i": 222, "j": 222, "k": 500, "l": 222, "m": 833, "n": 556,
    "o": 556, "p": 556, "q": 556, "r": 333, "s": 500, "t": 278, "u": 556,
    "v": 500, "w": 722, "x": 500, "y": 500, "z": 500,
    "0": 556, "1": 556, "2": 556, "3": 556, "4": 556, "5": 556,
    "6": 556, "7": 556, "8": 556, "9": 556,
    " ": 278, ",": 278, ".": 278, "-": 333, "'": 238,
}


def text_width(s, size):
    return sum(WIDTHS.get(ch, 500) for ch in s) * size / 1000.0


def esc(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def build_cover_content(title, date_str, title_size=36, date_size=24):
    """Build a plain (uncompressed) content stream for the cover page."""
    tw = text_width(title, title_size)
    dw = text_width(date_str, date_size)
    tx = (612 - tw) / 2.0
    ty = 500.0
    dx = (612 - dw) / 2.0
    dy = ty - 80.0
    rule_y = ty - 36.0
    content = (
        f"BT\n"
        f"/F1 {title_size} Tf\n"
        f"{tx:.2f} {ty:.2f} Td\n"
        f"({esc(title)}) Tj\n"
        f"1 0 0 1 {dx:.2f} {dy:.2f} Tm\n"
        f"/F1 {date_size} Tf\n"
        f"({esc(date_str)}) Tj\n"
        f"ET\n"
        f"0.30 0.35 0.45 RG\n"
        f"1.5 w\n"
        f"{tx:.2f} {rule_y:.2f} m\n"
        f"{tx + tw:.2f} {rule_y:.2f} l\n"
        f"S\n"
    ).encode("latin-1")
    return content


# ----------------------------- Main -----------------------------------------

def main():
    INPUT = "report.pdf"
    OUTPUT = "report_with_cover.pdf"

    today = datetime.date.today()
    date_str = today.strftime("%B %d, %Y")
    title = "Annual Financial Report"

    print(f"Current date: {date_str}")
    print(f"Title: {title}")

    # --- 1. Parse the original report -------------------------------------
    report_data = Path(INPUT).read_bytes()
    report_objs = parse_document(report_data)
    report_trailer = parse_trailer(report_data)

    catalog_ref = report_trailer.get("Root")
    assert isinstance(catalog_ref, Ref), catalog_ref
    catalog_num = catalog_ref.num
    catalog_tree = report_objs[catalog_num][0]
    assert isinstance(catalog_tree, Dict)
    pages_num = catalog_tree.get("Pages").num
    pages_tree = report_objs[pages_num][0]
    assert pages_tree.get("Type").s == "Pages"
    report_page_count = pages_tree.get("Count")
    print(f"report.pdf: {len(report_objs)} objects, {report_page_count} page(s)")

    # --- 2. Build the cover page objects (numbers 1..3) --------------------
    cover_stream = build_cover_content(title, date_str)
    cover_font = Dict([
        ("Type", Name("Font")),
        ("Subtype", Name("Type1")),
        ("BaseFont", Name("Helvetica-Bold")),
        ("Encoding", Name("WinAnsiEncoding")),
    ])
    cover_content = Dict([("Length", len(cover_stream))])

    COVER_PAGE_NUM = 3
    ROOT_PAGES_NUM = 13  # new root /Pages for the merged document
    cover_page = Dict([
        ("Contents", Ref(2, 0)),
        ("MediaBox", [0, 0, 612, 792]),
        ("Parent", Ref(ROOT_PAGES_NUM, 0)),
        ("Resources", Dict([
            ("Font", Dict([("F1", Ref(1, 0))])),
            ("ProcSet", [Name("PDF"), Name("Text")]),
        ])),
        ("Type", Name("Page")),
    ])

    # --- 3. Renumber report objects: offset by 3 (cover occupies 1..3) -----
    OFFSET = 3
    mapping = {n: n + OFFSET for n in report_objs}
    new_pages_num = mapping[pages_num]  # report's page-tree root
    new_info_num = mapping[report_trailer.get("Info").num]

    # New catalog: copy the original catalog but point at the new root Pages.
    new_catalog = renumber(catalog_tree, mapping)
    new_catalog.set("Pages", Ref(ROOT_PAGES_NUM, 0))
    new_catalog_num = 12

    # Report page tree root: add /Parent pointing to the new root Pages.
    report_pages_root = renumber(pages_tree, mapping)
    report_pages_root.set("Parent", Ref(ROOT_PAGES_NUM, 0))

    # New root Pages node: [cover page, report page tree root].
    new_root_pages = Dict([
        ("Count", report_page_count + 1),
        ("Kids", [Ref(COVER_PAGE_NUM, 0), Ref(new_pages_num, 0)]),
        ("Type", Name("Pages")),
    ])

    # --- 4. Serialize the merged document ----------------------------------
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    xref = {}  # objnum -> (offset, gen)

    def emit(num, tree, stream=None):
        offset = len(out)
        body = b"\n" + ser(tree) + b"\n"
        if stream is not None:
            body += b"stream\n" + stream + b"\nendstream\n"
        out += f"{num} 0 obj".encode() + body + b"endobj\n"
        xref[num] = (offset, 0)

    emit(1, cover_font)
    emit(2, cover_content, cover_stream)
    emit(3, cover_page)
    for n in sorted(report_objs):
        if n == catalog_num:  # replaced by the new catalog
            continue
        tree, stream = report_objs[n]
        emit(mapping[n], renumber(tree, mapping), stream)
    emit(new_catalog_num, new_catalog)
    emit(ROOT_PAGES_NUM, new_root_pages)

    size = max(xref) + 1
    xref_offset = len(out)
    out += b"xref\n"
    out += f"0 {size}\n".encode()
    out += b"0000000000 65535 f \n"
    for num in range(1, size):
        offset, gen = xref[num]
        out += f"{offset:010d} {gen:05d} n \n".encode()
    out += b"trailer\n"
    out += ser(Dict([
        ("Info", Ref(new_info_num, 0)),
        ("Root", Ref(new_catalog_num, 0)),
        ("Size", size),
    ]))
    out += b"\nstartxref\n"
    out += str(xref_offset).encode() + b"\n%%EOF\n"

    Path(OUTPUT).write_bytes(bytes(out))
    print(f"Wrote {OUTPUT} ({len(out)} bytes, {size - 1} objects)")

    # --- 5. Validate the merged document -----------------------------------
    validate(OUTPUT, title, date_str, report_page_count + 1)


def validate(path, title, date_str, expected_pages):
    data = Path(path).read_bytes()
    assert data.startswith(b"%PDF-"), "bad header"
    objs = parse_document(data)
    trailer = parse_trailer(data)

    # All indirect references must resolve.
    missing = []
    for num, (tree, _) in objs.items():
        refs = []
        collect_refs(tree, refs)
        for r in refs:
            if r.num not in objs:
                missing.append((num, r.num))
    for key in ("Root", "Info"):
        r = trailer.get(key)
        if isinstance(r, Ref) and r.num not in objs:
            missing.append(("trailer", r.num))
    assert not missing, f"unresolved refs: {missing}"

    # Stream /Length consistency.
    for num, (tree, stream) in objs.items():
        if stream is not None:
            assert tree.get("Length") == len(stream), f"obj {num} length mismatch"

    # Walk the page tree and count pages.
    root = trailer.get("Root")
    catalog = objs[root.num][0]
    pages_ref = catalog.get("Pages")
    stack = [pages_ref.num]
    visited = set()
    count = 0
    page_objs = []
    while stack:
        n = stack.pop()
        if n in visited:
            continue
        visited.add(n)
        tree, _ = objs[n][0], objs[n][1]
        t = tree.get("Type")
        if t is not None and t.s == "Pages":
            for kid in tree.get("Kids") or []:
                if isinstance(kid, Ref):
                    stack.append(kid.num)
        elif t is not None and t.s == "Page":
            count += 1
            page_objs.append(n)
        else:
            raise AssertionError(f"obj {n} is neither Page nor Pages: {t}")

    assert count == expected_pages, f"expected {expected_pages} pages, got {count}"
    print(f"Validation: {count} page(s) in merged document: {page_objs}")

    # Verify the cover page text is present in its content stream.
    cover_content_obj = objs[COVER_PAGE_NUM][0].get("Contents").num
    stream = objs[cover_content_obj][1]
    assert title.encode() in stream, "title not found in cover content"
    assert date_str.encode() in stream, "date not found in cover content"
    print(f"Validation: cover page contains title {title!r} and date {date_str!r}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Add a cover page (title + current date) to report.pdf using pure Python.

No external PDF libraries or CLI tools are available in this environment, so we
implement a minimal PDF object model, parser, serializer, and merger.
"""

import datetime
import re
from pathlib import Path

# ----------------------------- PDF object model -----------------------------

WS = b"\x00\t\n\x0c\r "


class Name:
    def __init__(self, s):
        self.s = s

    def __repr__(self):
        return "/" + self.s


class StringTok:
    """A PDF string, keeping the original token bytes verbatim."""

    def __init__(self, raw):
        self.raw = raw


class Ref:
    def __init__(self, num, gen=0):
        self.num = num
        self.gen = gen

    def __repr__(self):
        return f"{self.num} {self.gen} R"


class Keyword:
    def __init__(self, s):
        self.s = s


class Dict:
    def __init__(self, pairs=None):
        self.pairs = pairs if pairs is not None else []

    def get(self, key, default=None):
        for k, v in self.pairs:
            if k == key:
                return v
        return default

    def set(self, key, value):
        for i, (k, v) in enumerate(self.pairs):
            if k == key:
                self.pairs[i] = (key, value)
                return
        self.pairs.append((key, value))

    def keys(self):
        return [k for k, _ in self.pairs]


# ----------------------------- PDF value parser -----------------------------


class PDFParser:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.n = len(data)

    def skip_ws(self):
        d = self.data
        n = self.n
        while self.pos < n:
            c = d[self.pos]
            if c in WS:
                self.pos += 1
            elif c == 0x25:  # '%' comment
                while self.pos < n and d[self.pos] not in b"\r\n":
                    self.pos += 1
            else:
                break

    def parse_value(self):
        self.skip_ws()
        d = self.data
        c = d[self.pos]
        if c == ord("<"):
            if d[self.pos + 1:self.pos + 2] == b"<":
                return self.parse_dict()
            return self.parse_hex_string()
        if c == ord("("):
            return self.parse_literal_string()
        if c == ord("["):
            return self.parse_array()
        if c == ord("/"):
            return self.parse_name()
        if c in b"+-.0123456789":
            return self.parse_number_or_ref()
        m = re.match(rb"[A-Za-z]+", d[self.pos:])
        kw = m.group(0).decode()
        self.pos += len(m.group(0))
        return Keyword(kw)

    def parse_dict(self):
        self.pos += 2  # '<<'
        pairs = []
        while True:
            self.skip_ws()
            if self.data[self.pos:self.pos + 2] == b">>":
                self.pos += 2
                break
            key = self.parse_value()
            assert isinstance(key, Name), f"dict key not a name: {key!r}"
            val = self.parse_value()
            pairs.append((key.s, val))
        return Dict(pairs)

    def parse_array(self):
        self.pos += 1  # '['
        arr = []
        while True:
            self.skip_ws()
            if self.data[self.pos:self.pos + 1] == b"]":
                self.pos += 1
                break
            arr.append(self.parse_value())
        return arr

    def parse_name(self):
        d = self.data
        n = self.n
        self.pos += 1  # '/'
        start = self.pos
        while self.pos < n:
            c = d[self.pos]
            if c in WS or c in b"()<>[]{}/%":
                break
            self.pos += 1
        raw = d[start:self.pos]
        out = bytearray()
        i = 0
        while i < len(raw):
            if raw[i:i + 1] == b"#" and i + 2 < len(raw):
                out.append(int(raw[i + 1:i + 3], 16))
                i += 3
            else:
                out.append(raw[i])
                i += 1
        return Name(bytes(out).decode("latin-1"))

    def parse_literal_string(self):
        d = self.data
        n = self.n
        start = self.pos
        self.pos += 1  # '('
        depth = 1
        while self.pos < n and depth:
            c = d[self.pos]
            if c == 0x5C:  # backslash
                nxt = d[self.pos + 1:self.pos + 2]
                if nxt in (b"\r", b"\n"):
                    self.pos += 2
                    if nxt == b"\r" and d[self.pos:self.pos + 1] == b"\n":
                        self.pos += 1
                    continue
                self.pos += 2
                continue
            if c == ord("("):
                depth += 1
            elif c == ord(")"):
                depth -= 1
            self.pos += 1
        self.pos += 1  # closing ')'
        return StringTok(d[start:self.pos])

    def parse_hex_string(self):
        d = self.data
        start = self.pos
        self.pos += 1  # '<'
        while self.pos < self.n and d[self.pos] != ord(">"):
            self.pos += 1
        self.pos += 1
        return StringTok(d[start:self.pos])

    def parse_number_or_ref(self):
        d = self.data
        n = self.n
        start = self.pos
        while self.pos < n and d[self.pos] in b"+-.0123456789":
            self.pos += 1
        tok = d[start:self.pos]
        if b"." in tok:
            val = float(tok)
        else:
            val = int(tok)
        save = self.pos
        self.skip_ws()
        m2 = re.match(rb"(\d+)\s+", d[self.pos:])
        if m2:
            p2 = self.pos + m2.end()
            p3 = p2
            while p3 < n and d[p3] in WS:
                p3 += 1
            if d[p3:p3 + 1] == b"R":
                self.pos = p3 + 1
                return Ref(int(tok), int(m2.group(1)))
        self.pos = save
        return val


# ----------------------------- Document parsing -----------------------------

OBJ_PAT = re.compile(rb"(\d+)\s+(\d+)\s+obj\b")


def parse_document(data):
    """Return {objnum: (value_tree, stream_bytes_or_None)} for all objects."""
    objs = {}
    pos = 0
    while True:
        m = OBJ_PAT.search(data, pos)
        if not m:
            break
        num, gen = int(m.group(1)), int(m.group(2))
        p = PDFParser(data, m.end())
        tree = p.parse_value()
        stream = None
        if isinstance(tree, Dict):
            q = PDFParser(data, p.pos)
            q.skip_ws()
            if q.data[q.pos:q.pos + 6] == b"stream":
                s = q.pos + 6
                if data[s:s + 2] == b"\r\n":
                    s += 2
                elif data[s:s + 1] in (b"\n", b"\r"):
                    s += 1
                length = tree.get("Length")
                if isinstance(length, int):
                    stream = data[s:s + length]
                    e = s + length
                else:
                    e = data.find(b"endstream", s)
                    stream = data[s:e]
                e2 = data.find(b"endobj", e)
                pos = e2 + len(b"endobj")
                objs[num] = (tree, stream)
                continue
        e = data.find(b"endobj", p.pos)
        pos = e + len(b"endobj")
        objs[num] = (tree, None)
    return objs


def parse_trailer(data):
    """Return the trailer Dict (last 'trailer' keyword followed by a dict)."""
    for m in reversed(list(re.finditer(rb"\btrailer\b", data))):
        p = PDFParser(data, m.end())
        try:
            v = p.parse_value()
        except Exception:
            continue
        if isinstance(v, Dict) and v.get("Root") is not None:
            return v
    raise RuntimeError("No trailer with /Root found")


# ----------------------------- Serialization --------------------------------


def ser(v):
    if isinstance(v, Ref):
        return f"{v.num} {v.gen} R".encode()
    if isinstance(v, Name):
        return b"/" + v.s.encode("latin-1")
    if isinstance(v, StringTok):
        return v.raw
    if isinstance(v, Keyword):
        return v.s.encode()
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, float):
        return repr(v).encode()
    if isinstance(v, Dict):
        out = b"<<\n"
        for k, val in v.pairs:
            out += b"/" + k.encode("latin-1") + b" " + ser(val) + b"\n"
        return out + b">>"
    if isinstance(v, list):
        return b"[ " + b" ".join(ser(x) for x in v) + b" ]"
    raise TypeError(f"cannot serialize {type(v)}")


def renumber(tree, mapping):
    if isinstance(tree, Ref):
        return Ref(mapping.get(tree.num, tree.num), tree.gen)
    if isinstance(tree, Dict):
        return Dict([(k, renumber(v, mapping)) for k, v in tree.pairs])
    if isinstance(tree, list):
        return [renumber(v, mapping) for v in tree]
    return tree


def collect_refs(v, out):
    if isinstance(v, Ref):
        out.append(v)
    elif isinstance(v, Dict):
        for _, x in v.pairs:
            collect_refs(x, out)
    elif isinstance(v, list):
        for x in v:
            collect_refs(x, out)


# ----------------------------- Cover page content ---------------------------

# Helvetica-Bold AFM widths (per 1000 units) for the characters we need.
WIDTHS = {
    "A": 722, "B": 722, "C": 722, "D": 722, "E": 667, "F": 611, "G": 778,
    "H": 722, "I": 278, "J": 556, "K": 722, "L": 611, "M": 833, "N": 722,
    "O": 778, "P": 667, "Q": 778, "R": 722, "S": 667, "T": 611, "U": 722,
    "V": 667, "W": 944, "X": 667, "Y": 667, "Z": 611,
    "a": 556, "b": 556, "c": 500, "d": 556, "e": 556, "f": 278, "g": 556,
    "h": 556, "i": 222, "j": 222, "k": 500, "l": 222, "m": 833, "n": 556,
    "o": 556, "p": 556, "q": 556, "r": 333, "s": 500, "t": 278, "u": 556,
    "v": 500, "w": 722, "x": 500, "y": 500, "z": 500,
    "0": 556, "1": 556, "2": 556, "3": 556, "4": 556, "5": 556,
    "6": 556, "7": 556, "8": 556, "9": 556,
    " ": 278, ",": 278, ".": 278, "-": 333, "'": 238,
}


def text_width(s, size):
    return sum(WIDTHS.get(ch, 500) for ch in s) * size / 1000.0


def esc(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def build_cover_content(title, date_str, title_size=36, date_size=24):
    """Build a plain (uncompressed) content stream for the cover page."""
    tw = text_width(title, title_size)
    dw = text_width(date_str, date_size)
    tx = (612 - tw) / 2.0
    ty = 500.0
    dx = (612 - dw) / 2.0
    dy = ty - 80.0
    rule_y = ty - 36.0
    content = (
        f"BT\n"
        f"/F1 {title_size} Tf\n"
        f"{tx:.2f} {ty:.2f} Td\n"
        f"({esc(title)}) Tj\n"
        f"1 0 0 1 {dx:.2f} {dy:.2f} Tm\n"
        f"/F1 {date_size} Tf\n"
        f"({esc(date_str)}) Tj\n"
        f"ET\n"
        f"0.30 0.35 0.45 RG\n"
        f"1.5 w\n"
        f"{tx:.2f} {rule_y:.2f} m\n"
        f"{tx + tw:.2f} {rule_y:.2f} l\n"
        f"S\n"
    ).encode("latin-1")
    return content


# ----------------------------- Main -----------------------------------------

def main():
    INPUT = "report.pdf"
    OUTPUT = "report_with_cover.pdf"

    today = datetime.date.today()
    date_str = today.strftime("%B %d, %Y")
    title = "Annual Financial Report"

    print(f"Current date: {date_str}")
    print(f"Title: {title}")

    # --- 1. Parse the original report -------------------------------------
    report_data = Path(INPUT).read_bytes()
    report_objs = parse_document(report_data)
    report_trailer = parse_trailer(report_data)

    catalog_ref = report_trailer.get("Root")
    assert isinstance(catalog_ref, Ref), catalog_ref
    catalog_num = catalog_ref.num
    catalog_tree = report_objs[catalog_num][0]
    assert isinstance(catalog_tree, Dict)
    pages_num = catalog_tree.get("Pages").num
    pages_tree = report_objs[pages_num][0]
    assert pages_tree.get("Type").s == "Pages"
    report_page_count = pages_tree.get("Count")
    print(f"report.pdf: {len(report_objs)} objects, {report_page_count} page(s)")

    # --- 2. Build the cover page objects (numbers 1..3) --------------------
    cover_stream = build_cover_content(title, date_str)
    cover_font = Dict([
        ("Type", Name("Font")),
        ("Subtype", Name("Type1")),
        ("BaseFont", Name("Helvetica-Bold")),
        ("Encoding", Name("WinAnsiEncoding")),
    ])
    cover_content = Dict([("Length", len(cover_stream))])

    COVER_PAGE_NUM = 3
    ROOT_PAGES_NUM = 13  # new root /Pages for the merged document
    cover_page = Dict([
        ("Contents", Ref(2, 0)),
        ("MediaBox", [0, 0, 612, 792]),
        ("Parent", Ref(ROOT_PAGES_NUM, 0)),
        ("Resources", Dict([
            ("Font", Dict([("F1", Ref(1, 0))])),
            ("ProcSet", [Name("PDF"), Name("Text")]),
        ])),
        ("Type", Name("Page")),
    ])

    # --- 3. Renumber report objects: offset by 3 (cover occupies 1..3) -----
    OFFSET = 3
    mapping = {n: n + OFFSET for n in report_objs}
    new_pages_num = mapping[pages_num]  # report's page-tree root
    new_info_num = mapping[report_trailer.get("Info").num]

    # New catalog: copy the original catalog but point at the new root Pages.
    new_catalog = renumber(catalog_tree, mapping)
    new_catalog.set("Pages", Ref(ROOT_PAGES_NUM, 0))
    new_catalog_num = 12

    # Report page tree root: add /Parent pointing to the new root Pages.
    report_pages_root = renumber(pages_tree, mapping)
    report_pages_root.set("Parent", Ref(ROOT_PAGES_NUM, 0))

    # New root Pages node: [cover page, report page tree root].
    new_root_pages = Dict([
        ("Count", report_page_count + 1),
        ("Kids", [Ref(COVER_PAGE_NUM, 0), Ref(new_pages_num, 0)]),
        ("Type", Name("Pages")),
    ])

    # --- 4. Serialize the merged document ----------------------------------
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    xref = {}  # objnum -> (offset, gen)

    def emit(num, tree, stream=None):
        nonlocal out, xref
        offset = len(out)
        body = b"\n" + ser(tree) + b"\n"
        if stream is not None:
            body += b"stream\n" + stream + b"\nendstream\n"
        out += f"{num} 0 obj".encode() + body + b"endobj\n"
        xref[num] = (offset, 0)

    emit(1, cover_font)
    emit(2, cover_content, cover_stream)
    emit(3, cover_page)
    for n in sorted(report_objs):
        if n == catalog_num:  # replaced by the new catalog
            continue
        tree, stream = report_objs[n]
        emit(mapping[n], renumber(tree, mapping), stream)
    emit(new_catalog_num, new_catalog)
    emit(ROOT_PAGES_NUM, new_root_pages)

    size = max(xref) + 1
    xref_offset = len(out)
    out += b"xref\n"
    out += f"0 {size}\n".encode()
    out += b"0000000000 65535 f \n"
    for num in range(1, size):
        offset, gen = xref[num]
        out += f"{offset:010d} {gen:05d} n \n".encode()
    out += b"trailer\n"
    out += ser(Dict([
        ("Info", Ref(new_info_num, 0)),
        ("Root", Ref(new_catalog_num, 0)),
        ("Size", size),
    ]))
    out += b"\nstartxref\n"
    out += str(xref_offset).encode() + b"\n%%EOF\n"

    Path(OUTPUT).write_bytes(bytes(out))
    print(f"Wrote {OUTPUT} ({len(out)} bytes, {size - 1} objects)")

    # --- 5. Validate the merged document -----------------------------------
    validate(OUTPUT, title, date_str, report_page_count + 1)


def validate(path, title, date_str, expected_pages):
    data = Path(path).read_bytes()
    assert data.startswith(b"%PDF-"), "bad header"
    objs = parse_document(data)
    trailer = parse_trailer(data)

    # All indirect references must resolve.
    missing = []
    for num, (tree, _) in objs.items():
        refs = []
        collect_refs(tree, refs)
        for r in refs:
            if r.num not in objs:
                missing.append((num, r.num))
    for key in ("Root", "Info"):
        r = trailer.get(key)
        if isinstance(r, Ref) and r.num not in objs:
            missing.append(("trailer", r.num))
    assert not missing, f"unresolved refs: {missing}"

    # Stream /Length consistency.
    for num, (tree, stream) in objs.items():
        if stream is not None:
            assert tree.get("Length") == len(stream), f"obj {num} length mismatch"

    # Walk the page tree and count pages.
    root = trailer.get("Root")
    catalog = objs[root.num][0]
    pages_ref = catalog.get("Pages")
    stack = [pages_ref.num]
    visited = set()
    count = 0
    page_objs = []
    while stack:
        n = stack.pop()
        if n in visited:
            continue
        visited.add(n)
        tree, _ = objs[n][0], objs[n][1]
        t = tree.get("Type")
        if t is not None and t.s == "Pages":
            for kid in tree.get("Kids") or []:
                if isinstance(kid, Ref):
                    stack.append(kid.num)
        elif t is not None and t.s == "Page":
            count += 1
            page_objs.append(n)
        else:
            raise AssertionError(f"obj {n} is neither Page nor Pages: {t}")

    assert count == expected_pages, f"expected {expected_pages} pages, got {count}"
    print(f"Validation: {count} page(s) in merged document: {page_objs}")

    # Verify the cover page text is present in its content stream.
    cover_content_obj = objs[COVER_PAGE_NUM][0].get("Contents").num
    stream = objs[cover_content_obj][1]
    assert title.encode() in stream, "title not found in cover content"
    assert date_str.encode() in stream, "date not found in cover content"
    print(f"Validation: cover page contains title {title!r} and date {date_str!r}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Add a cover page (title + current date) to report.pdf using pure Python.

No external PDF libraries or CLI tools are available in this environment, so we
implement a minimal PDF object model, parser, serializer, and merger.
"""

import datetime
import re
from pathlib import Path

# ----------------------------- PDF object model -----------------------------

WS = b"\x00\t\n\x0c\r "


class Name:
    def __init__(self, s):
        self.s = s

    def __repr__(self):
        return "/" + self.s


class StringTok:
    """A PDF string, keeping the original token bytes verbatim."""

    def __init__(self, raw):
        self.raw = raw


class Ref:
    def __init__(self, num, gen=0):
        self.num = num
        self.gen = gen

    def __repr__(self):
        return f"{self.num} {self.gen} R"


class Keyword:
    def __init__(self, s):
        self.s = s


class Dict:
    def __init__(self, pairs=None):
        self.pairs = pairs if pairs is not None else []

    def get(self, key, default=None):
        for k, v in self.pairs:
            if k == key:
                return v
        return default

    def set(self, key, value):
        for i, (k, v) in enumerate(self.pairs):
            if k == key:
                self.pairs[i] = (key, value)
                return
        self.pairs.append((key, value))

    def keys(self):
        return [k for k, _ in self.pairs]


# ----------------------------- PDF value parser -----------------------------


class PDFParser:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.n = len(data)

    def skip_ws(self):
        d = self.data
        n = self.n
        while self.pos < n:
            c = d[self.pos]
            if c in WS:
                self.pos += 1
            elif c == 0x25:  # '%' comment
                while self.pos < n and d[self.pos] not in b"\r\n":
                    self.pos += 1
            else:
                break

    def parse_value(self):
        self.skip_ws()
        d = self.data
        c = d[self.pos]
        if c == ord("<"):
            if d[self.pos + 1:self.pos + 2] == b"<":
                return self.parse_dict()
            return self.parse_hex_string()
        if c == ord("("):
            return self.parse_literal_string()
        if c == ord("["):
            return self.parse_array()
        if c == ord("/"):
            return self.parse_name()
        if c in b"+-.0123456789":
            return self.parse_number_or_ref()
        m = re.match(rb"[A-Za-z]+", d[self.pos:])
        kw = m.group(0).decode()
        self.pos += len(m.group(0))
        return Keyword(kw)

    def parse_dict(self):
        self.pos += 2  # '<<'
        pairs = []
        while True:
            self.skip_ws()
            if self.data[self.pos:self.pos + 2] == b">>":
                self.pos += 2
                break
            key = self.parse_value()
            assert isinstance(key, Name), f"dict key not a name: {key!r}"
            val = self.parse_value()
            pairs.append((key.s, val))
        return Dict(pairs)

    def parse_array(self):
        self.pos += 1  # '['
        arr = []
        while True:
            self.skip_ws()
            if self.data[self.pos:self.pos + 1] == b"]":
                self.pos += 1
                break
            arr.append(self.parse_value())
        return arr

    def parse_name(self):
        d = self.data
        n = self.n
        self.pos += 1  # '/'
        start = self.pos
        while self.pos < n:
            c = d[self.pos]
            if c in WS or c in b"()<>[]{}/%":
                break
            self.pos += 1
        raw = d[start:self.pos]
        out = bytearray()
        i = 0
        while i < len(raw):
            if raw[i:i + 1] == b"#" and i + 2 < len(raw):
                out.append(int(raw[i + 1:i + 3], 16))
                i += 3
            else:
                out.append(raw[i])
                i += 1
        return Name(bytes(out).decode("latin-1"))

    def parse_literal_string(self):
        d = self.data
        n = self.n
        start = self.pos
        self.pos += 1  # '('
        depth = 1
        while self.pos < n and depth:
            c = d[self.pos]
            if c == 0x5C:  # backslash
                nxt = d[self.pos + 1:self.pos + 2]
                if nxt in (b"\r", b"\n"):
                    self.pos += 2
                    if nxt == b"\r" and d[self.pos:self.pos + 1] == b"\n":
                        self.pos += 1
                    continue
                self.pos += 2
                continue
            if c == ord("("):
                depth += 1
            elif c == ord(")"):
                depth -= 1
            self.pos += 1
        self.pos += 1  # closing ')'
        return StringTok(d[start:self.pos])

    def parse_hex_string(self):
        d = self.data
        start = self.pos
        self.pos += 1  # '<'
        while self.pos < self.n and d[self.pos] != ord(">"):
            self.pos += 1
        self.pos += 1
        return StringTok(d[start:self.pos])

    def parse_number_or_ref(self):
        d = self.data
        n = self.n
        start = self.pos
        while self.pos < n and d[self.pos] in b"+-.0123456789":
            self.pos += 1
        tok = d[start:self.pos]
        if b"." in tok:
            val = float(tok)
        else:
            val = int(tok)
        save = self.pos
        self.skip_ws()
        m2 = re.match(rb"(\d+)\s+", d[self.pos:])
        if m2:
            p2 = self.pos + m2.end()
            p3 = p2
            while p3 < n and d[p3] in WS:
                p3 += 1
            if d[p3:p3 + 1] == b"R":
                self.pos = p3 + 1
                return Ref(int(tok), int(m2.group(1)))
        self.pos = save
        return val


# ----------------------------- Document parsing -----------------------------

OBJ_PAT = re.compile(rb"(\d+)\s+(\d+)\s+obj\b")


def parse_document(data):
    """Return {objnum: (value_tree, stream_bytes_or_None)} for all objects."""
    objs = {}
    pos = 0
    while True:
        m = OBJ_PAT.search(data, pos)
        if not m:
            break
        num, gen = int(m.group(1)), int(m.group(2))
        p = PDFParser(data, m.end())
        tree = p.parse_value()
        stream = None
        if isinstance(tree, Dict):
            q = PDFParser(data, p.pos)
            q.skip_ws()
            if q.data[q.pos:q.pos + 6] == b"stream":
                s = q.pos + 6
                if data[s:s + 2] == b"\r\n":
                    s += 2
                elif data[s:s + 1] in (b"\n", b"\r"):
                    s += 1
                length = tree.get("Length")
                if isinstance(length, int):
                    stream = data[s:s + length]
                    e = s + length
                else:
                    e = data.find(b"endstream", s)
                    stream = data[s:e]
                e2 = data.find(b"endobj", e)
                pos = e2 + len(b"endobj")
                objs[num] = (tree, stream)
                continue
        e = data.find(b"endobj", p.pos)
        pos = e + len(b"endobj")
        objs[num] = (tree, None)
    return objs


def parse_trailer(data):
    """Return the trailer Dict (last 'trailer' keyword followed by a dict)."""
    for m in reversed(list(re.finditer(rb"\btrailer\b", data))):
        p = PDFParser(data, m.end())
        try:
            v = p.parse_value()
        except Exception:
            continue
        if isinstance(v, Dict) and v.get("Root") is not None:
            return v
    raise RuntimeError("No trailer with /Root found")


# ----------------------------- Serialization --------------------------------


def ser(v):
    if isinstance(v, Ref):
        return f"{v.num} {v.gen} R".encode()
    if isinstance(v, Name):
        return b"/" + v.s.encode("latin-1")
    if isinstance(v, StringTok):
        return v.raw
    if isinstance(v, Keyword):
        return v.s.encode()
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, float):
        return repr(v).encode()
    if isinstance(v, Dict):
        out = b"<<\n"
        for k, val in v.pairs:
            out += b"/" + k.encode("latin-1") + b" " + ser(val) + b"\n"
        return out + b">>"
    if isinstance(v, list):
        return b"[ " + b" ".join(ser(x) for x in v) + b" ]"
    raise TypeError(f"cannot serialize {type(v)}")


def renumber(tree, mapping):
    if isinstance(tree, Ref):
        return Ref(mapping.get(tree.num, tree.num), tree.gen)
    if isinstance(tree, Dict):
        return Dict([(k, renumber(v, mapping)) for k, v in tree.pairs])
    if isinstance(tree, list):
        return [renumber(v, mapping) for v in tree]
    return tree


def collect_refs(v, out):
    if isinstance(v, Ref):
        out.append(v)
    elif isinstance(v, Dict):
        for _, x in v.pairs:
            collect_refs(x, out)
    elif isinstance(v, list):
        for x in v:
            collect_refs(x, out)


